def display_image(batch, labels=None, n=8):
    batch = batch.detach().numpy()
    fig, axs = plt.subplots(1, n, figsize=(12, 2))
    for i in range(n):
        axs[i].imshow(batch[i, 0, :, :], cmap='gray')
        axs[i].axis('off')
        if labels is not None:
            axs[i].set_title(labels[i].item())
